def Bspline(xi, i, p, Xi):
    '''Inputs:
    xi : knot index, integer
    i : polynomial index , integer
    p : polynomial degree of basis function , integer
    Xi : knot vector, 1d array of arbitrary size
    Outputs:
    1d array of size 1，2 or 3
    '''
    # Base case: degree 0
    if p == 0:
        if Xi[i] <= xi < Xi[i+1]:
            return np.array([1.0])
        else:
            return np.array([0.0])

    # Recursive case: degree > 0
    # Calculate the two coefficients
    # First term coefficient: (xi - Xi[i]) / (Xi[i+p] - Xi[i])
    denom1 = Xi[i+p] - Xi[i]
    if denom1 == 0:
        alpha = 0.0
    else:
        alpha = (xi - Xi[i]) / denom1

    # Second term coefficient: (Xi[i+p+1] - xi) / (Xi[i+p+1] - Xi[i+1])
    denom2 = Xi[i+p+1] - Xi[i+1]
    if denom2 == 0:
        beta = 0.0
    else:
        beta = (Xi[i+p+1] - xi) / denom2

    # Recursive calls
    return alpha * Bspline(xi, i, p-1, Xi) + beta * Bspline(xi, i+1, p-1, Xi)
